#include "agentcad/markup.hpp"
#include "agentcad/service.hpp"
#include "agentcad/storage.hpp"
#include "agentcad/runtime.hpp"
#include "agentcad/jobs.hpp"
#include "agentcad/render_settings.hpp"
#include <chrono>
#include <future>
#include <functional>
#include <iostream>
#include <thread>

using namespace agentcad;
namespace {
int checks=0;
void check(bool value,const char* message){if(!value)throw std::runtime_error(message);++checks;}
void fails(const std::function<void()>& fn){try{fn();}catch(const Error& e){check(e.code=="invalid_argument","Typed markup validation error");return;}throw std::runtime_error("Expected markup validation failure");}
Json binding(){return {{"source",{{"view_id","review"},{"document_id","plate"},{"revision",1},{"evaluation_id","eval_plate"},{"feature_id","body"},{"review_sha256",nullptr},{"draft",false}}},{"frame",{{"camera",{{"yaw",0},{"pitch",0},{"zoom",1},{"pan",{0,0}}}},{"hidden_part_ids",Json::array()},{"presentation",nullptr},{"appearance",nullptr},{"render",nullptr},{"artifact_pose",nullptr},{"section",nullptr},{"annotations",Json::array()}}},{"viewport",{640,480}}};}
Json scene(){return {{"schema_version",1},{"binding",binding()},{"items",Json::array({{{"id","mark_one"},{"kind","arrow"},{"color","#e63946"},{"width",3},{"points",{{.1,.2},{.4,.6}}}}})}};}
void run(){
 const auto good=scene();validate_markup_scene(good);check(markup_matches(good,binding()),"Current source frame matches");check(markup_context(good,binding()).at("status")=="current","Current native context");check(markup_context(nullptr,binding()).at("status")=="empty","Missing markup context");
 auto frame=binding();frame["source"]["evaluation_id"]="eval_next";check(!markup_matches(good,frame)&&markup_context(good,frame).at("status")=="retired","Different evaluation retires coordinates");frame=binding();frame["frame"]["camera"]["yaw"]=.1;check(!markup_matches(good,frame),"Different camera retires coordinates");frame=binding();frame["viewport"]={1280,960};check(markup_matches(good,frame),"Proportional viewport preserves coordinates");frame["viewport"]={1000,960};check(!markup_matches(good,frame)&&markup_matches(good,frame,false),"Native context can omit unavailable viewport geometry");
 for(const auto& kind:{"pen","line","arrow","rectangle","ellipse","text"}){auto value=good;auto& item=value["items"][0];item["kind"]=kind;if(std::string(kind)=="text"){item["points"]={{.1,.2}};item["text"]="Change this\nØ 4";item["font_size"]=20;}validate_markup_scene(value);++checks;}
 const std::function<void(Json&)> invalid[]={[](Json& v){v["schema_version"]=2;},[](Json& v){v["execute"]="shell";},[](Json& v){v["binding"]["source"]["revision"]=0;},[](Json& v){v["binding"]["source"]["review_sha256"]="a";},[](Json& v){v["binding"]["frame"]["camera"]["zoom"]=0;},[](Json& v){v["binding"]["frame"]["hidden_part_ids"]={"a","a"};},[](Json& v){v["binding"]["frame"]["extra"]=true;},[](Json& v){v["binding"]["viewport"]={640,0};},[](Json& v){v["items"][0]["points"][0][0]=-1;},[](Json& v){v["items"][0]["kind"]="javascript";},[](Json& v){v["items"][0]["width"]=17;},[](Json& v){v["items"][0]["color"]="url(x)";},[](Json& v){v["items"].push_back(v["items"][0]);}};
 for(const auto& alter:invalid){auto value=good;alter(value);fails([&]{validate_markup_scene(value);});check(good==scene(),"Rejected validation preserves original scene");}
 auto text=good;text["items"][0].update({{"kind","text"},{"points",{{.1,.2}}},{"font_size",20},{"text","Label"}});for(const auto& label:{std::string(" "),std::string("\x01"),std::string(513,'x'),std::string("a\na\na\na\na\na\na\na\na")}){text["items"][0]["text"]=label;fails([&]{validate_markup_scene(text);});}
 auto huge=good;huge["items"][0]["kind"]="pen";huge["items"][0]["points"]=Json::array();for(int n=0;n<2049;++n)huge["items"][0]["points"].push_back({0,0});fails([&]{validate_markup_scene(huge);});huge["items"][0]["points"].erase(2048);validate_markup_scene(huge);for(int n=1;n<5;++n){auto item=huge["items"][0];item["id"]="m"+std::to_string(n);huge["items"].push_back(item);}fails([&]{validate_markup_scene(huge);});
 auto artifact=good;artifact["binding"]["source"].update({{"document_id",nullptr},{"revision",nullptr},{"feature_id",nullptr},{"review_sha256",std::string(64,'a')}});validate_markup_scene(artifact);check(markup_context(artifact,artifact.at("binding")).at("status")=="current","Read-only artifact markup is explicitly qualified");artifact["binding"]["source"]["draft"]=true;fails([&]{validate_markup_scene(artifact);});
 check(markup_scene_schema().at("additionalProperties")==false&&markup_context_schema().at("additionalProperties")==false,"Schemas expose closed scene and context");
}
Json call(Service& service,const std::string& tool,Json arguments){for(int n=0;;++n){try{return service.call(tool,arguments);}catch(const Error& e){if(e.code!="workspace_busy"||n==1000)throw;}std::this_thread::sleep_for(std::chrono::milliseconds(2));}}
Json ready(Service& service){for(int n=0;n<1000;++n){auto result=call(service,"cad_viewer",{{"action","sync"},{"view_id","review"}});if(result.at("state")=="ready")return result;if(result.at("state")=="error")throw std::runtime_error(result.dump());std::this_thread::sleep_for(std::chrono::milliseconds(5));}throw std::runtime_error("Markup viewer did not become ready");}
Json from_context(const Json& context){
 return {{"source",{{"view_id",context.at("view_id")},{"document_id",context.at("document_id")},{"revision",context.at("revision")},{"evaluation_id",context.at("evaluation_id")},{"feature_id",context.at("feature_id")},{"review_sha256",context.contains("artifact")?context.at("artifact").at("review_sha256"):Json(nullptr)},{"draft",context.value("draft",false)}}},
  {"frame",{{"camera",context.value("camera",Json{{"yaw",-.65},{"pitch",.6},{"zoom",1},{"pan",{0,0}}})},{"hidden_part_ids",context.at("hidden_part_ids")},{"presentation",context.at("presentation")},{"appearance",context.at("appearance")},{"render",context.at("render")},{"artifact_pose",context.value("read_only",false)?context.value("artifact_pose",Json::object()):Json(nullptr)},{"section",context.value("section",Json(nullptr))},{"annotations",context.at("annotations")}}},{"viewport",{640,480}}};
}
void service_run(){
 const auto root=fs::temp_directory_path()/("cad-markup-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()));directory(root);
 struct Cleanup{fs::path path;~Cleanup(){std::error_code e;fs::remove_all(path,e);}} cleanup{root};Service service(root);
 const Json model={{"schema_version",1},{"units","mm"},{"parameters",Json::object()},{"features",Json::array({{{"id","body"},{"type","box"},{"size",{20,10,6}}}})},{"output","body"}};
 call(service,"cad_create",{{"document_id","plate"},{"model",model}});call(service,"cad_open",{{"document_id","plate"},{"view_id","review"}});auto shown=ready(service),context=call(service,"cad_context",{{"view_id","review"}});const auto head=read_text(root/"documents/plate/HEAD.json"),revision=read_text(root/"documents/plate/revisions/1.json");auto saved=scene();saved["binding"]=from_context(context);
 auto publish=[&](Service& target,Json extra){Json request={{"action","context"},{"view_id","review"},{"evaluation_id",shown.at("evaluation_id")},{"selection",nullptr}};request.update(extra);return call(target,"cad_viewer",request);};
 auto result=publish(service,{{"markup",saved},{"camera",saved.at("binding").at("frame").at("camera")}});check(result.at("markup").at("scene")==saved&&result.at("markup").at("status")=="current","Native publication persists a qualified scene");check(ready(service).at("markup").at("scene")==saved,"Native sync includes saved markup");Service reopened(root);check(call(reopened,"cad_context",{{"view_id","review"}}).at("markup").at("scene")==saved,"Reopened service restores exact bounded markup");
 const auto before=read_text(root/"views/review/state.json");auto forged=saved;forged["binding"]["frame"]["camera"]["yaw"]=.2;try{publish(service,{{"markup",forged}});throw std::runtime_error("Expected stale markup rejection");}catch(const Error& e){check(e.code=="stale_markup","Changed frame returns stale_markup");}check(read_text(root/"views/review/state.json")==before,"Rejected markup preserves saved native state");
 auto changed_camera=saved.at("binding").at("frame").at("camera");changed_camera["yaw"]=.3;result=publish(service,{{"camera",changed_camera},{"markup",saved}});check(result.at("markup").at("status")=="retired"&&result.at("markup").at("scene")==saved,"Camera change preserves historical coordinates and marks retired");publish(service,{{"camera",saved.at("binding").at("frame").at("camera")}});check(call(service,"cad_context",{{"view_id","review"}}).at("markup").at("status")=="current","Exact original camera restores original screen-space interpretation");
 result=publish(service,{{"viewport",{800,480}}});check(result.at("markup").at("status")=="retired","Changed viewport aspect retires native context");result=publish(service,{{"viewport",{1280,960}}});check(result.at("markup").at("status")=="current","Proportional viewport preserves native frame binding");publish(service,{{"viewport",{640,480}}});
 // Capture admission fingerprints saved markup independently from geometry.
 auto pending=std::async(std::launch::async,[&]{return call(service,"cad_screenshot",{{"view_id","review"},{"timeout_ms",3000}});});bool requested=false;for(int n=0;n<500;++n){auto sync=ready(service);if(sync.contains("capture_requests")&&!sync.at("capture_requests").empty()){requested=true;break;}std::this_thread::sleep_for(std::chrono::milliseconds(2));}check(requested,"Screenshot was admitted before markup changed");auto edited=saved;edited["items"][0]["points"][1]={.7,.8};publish(service,{{"markup",edited}});try{(void)pending.get();throw std::runtime_error("Expected changed-markup capture rejection");}catch(const Error& e){check(e.code=="stale_capture","Markup change invalidates an admitted screenshot frame");}
 check(read_text(root/"documents/plate/HEAD.json")==head&&read_text(root/"documents/plate/revisions/1.json")==revision,"Markup persistence and capture rejection preserve editable source/history bytes");
 call(service,"cad_apply",{{"document_id","plate"},{"expected_revision",1},{"operations",Json::array({{{"op","replace_feature"},{"id","body"},{"feature",{{"id","body"},{"type","box"},{"size",{22,10,6}}}}}})}});check(call(service,"cad_context",{{"view_id","review"}}).at("markup").at("status")=="retired","New HEAD retires markup before display rebuild");shown=ready(service);result=call(service,"cad_context",{{"view_id","review"}});check(result.at("markup").at("scene")==edited&&result.at("markup").at("status")=="retired","New evaluation preserves old frame evidence without rebinding");publish(service,{{"markup",nullptr}});check(call(service,"cad_context",{{"view_id","review"}}).at("markup").at("status")=="empty","Explicit clear removes historical markup");check(read_text(root/"documents/plate/revisions/1.json")==revision,"Historical source remains immutable after later source edit");
}
}
int main(){try{set_worker_executable(CAD_SERVICE_EXE);run();service_run();std::cout<<"markup: "<<checks<<" checks passed\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
